cat > /workspace/src/cmd.go << 'GOEOF'
package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

// Global flags
type GlobalFlags struct {
	Backend      string
	S3Bucket     string
	KMSKeyAlias  string
	Retries      int
	RetryMode    string
	Verbose      bool
}

type ChamberApp struct {
	globals GlobalFlags
	args    []string
}

func NewChamberApp() *ChamberApp {
	return &ChamberApp{}
}

func (a *ChamberApp) Execute() error {
	args := os.Args[1:]

	// Parse global flags first
	remaining, err := a.parseGlobalFlags(args)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %s\n", err)
		a.printRootUsage()
		return err
	}

	if len(remaining) == 0 {
		a.printRootUsage()
		return nil
	}

	cmd := remaining[0]
	cmdArgs := remaining[1:]

	switch cmd {
	case "version":
		return a.runVersion(cmdArgs)
	case "write":
		return a.runWrite(cmdArgs)
	case "read":
		return a.runRead(cmdArgs)
	case "list":
		return a.runList(cmdArgs)
	case "list-services":
		return a.runListServices(cmdArgs)
	case "delete":
		return a.runDelete(cmdArgs)
	case "history":
		return a.runHistory(cmdArgs)
	case "exec":
		return a.runExec(cmdArgs)
	case "env":
		return a.runEnv(cmdArgs)
	case "export":
		return a.runExport(cmdArgs)
	case "import":
		return a.runImport(cmdArgs)
	case "find":
		return a.runFind(cmdArgs)
	case "tag":
		return a.runTag(cmdArgs)
	case "completion":
		return a.runCompletion(cmdArgs)
	case "help":
		return a.runHelp(cmdArgs)
	case "--help", "-h":
		a.printRootUsage()
		return nil
	default:
		fmt.Fprintf(os.Stderr, "Error: unknown command %q for \"chamber\"\nRun 'chamber --help' for usage.\n", cmd)
		return fmt.Errorf("unknown command")
	}
}

func (a *ChamberApp) parseGlobalFlags(args []string) ([]string, error) {
	// Set defaults
	a.globals.Backend = getEnvOrDefault("CHAMBER_SECRET_BACKEND", "ssm")
	a.globals.KMSKeyAlias = getEnvOrDefault("CHAMBER_KMS_KEY_ALIAS", "alias/parameter_store_key")
	a.globals.Retries = 10
	a.globals.RetryMode = "standard"

	if r := os.Getenv("CHAMBER_RETRIES"); r != "" {
		if n, err := strconv.Atoi(r); err == nil {
			a.globals.Retries = n
		}
	}

	remaining := []string{}
	i := 0
	for i < len(args) {
		arg := args[i]
		switch arg {
		case "-b", "--backend":
			i++
			if i >= len(args) {
				return nil, fmt.Errorf("flag needs an argument: '--backend'")
			}
			a.globals.Backend = args[i]
		case "--backend-s3-bucket":
			i++
			if i >= len(args) {
				return nil, fmt.Errorf("flag needs an argument: '--backend-s3-bucket'")
			}
			a.globals.S3Bucket = args[i]
		case "--kms-key-alias":
			i++
			if i >= len(args) {
				return nil, fmt.Errorf("flag needs an argument: '--kms-key-alias'")
			}
			a.globals.KMSKeyAlias = args[i]
		case "-r", "--retries":
			i++
			if i >= len(args) {
				return nil, fmt.Errorf("flag needs an argument: '--retries'")
			}
			n, err := strconv.Atoi(args[i])
			if err != nil {
				return nil, fmt.Errorf("invalid argument %q for '--retries' flag: %s", args[i], err)
			}
			a.globals.Retries = n
		case "--retry-mode":
			i++
			if i >= len(args) {
				return nil, fmt.Errorf("flag needs an argument: '--retry-mode'")
			}
			a.globals.RetryMode = args[i]
		case "--verbose":
			a.globals.Verbose = true
		case "-h", "--help":
			// Pass to command
			remaining = append(remaining, arg)
		default:
			if strings.HasPrefix(arg, "-b=") {
				a.globals.Backend = arg[3:]
			} else if strings.HasPrefix(arg, "--backend=") {
				a.globals.Backend = arg[10:]
			} else if strings.HasPrefix(arg, "--backend-s3-bucket=") {
				a.globals.S3Bucket = arg[20:]
			} else if strings.HasPrefix(arg, "--kms-key-alias=") {
				a.globals.KMSKeyAlias = arg[16:]
			} else if strings.HasPrefix(arg, "-r=") {
				n, err := strconv.Atoi(arg[3:])
				if err == nil {
					a.globals.Retries = n
				}
			} else if strings.HasPrefix(arg, "--retries=") {
				n, err := strconv.Atoi(arg[10:])
				if err == nil {
					a.globals.Retries = n
				}
			} else if strings.HasPrefix(arg, "--retry-mode=") {
				a.globals.RetryMode = arg[13:]
			} else {
				// Not a global flag - add to remaining
				remaining = append(remaining, args[i:]...)
				return remaining, nil
			}
		}
		i++
	}
	return remaining, nil
}

func getEnvOrDefault(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

func (a *ChamberApp) getStore() (SecretStore, error) {
	backend := strings.ToUpper(strings.TrimSpace(a.globals.Backend))
	switch backend {
	case "NULL":
		return &NullStore{}, nil
	case "SSM":
		return newSSMStore(a.globals.Retries, a.globals.RetryMode)
	case "SECRETSMANAGER":
		return newSecretsManagerStore(a.globals.Retries)
	case "S3":
		if a.globals.S3Bucket == "" {
			if b := os.Getenv("CHAMBER_S3_BUCKET"); b != "" {
				a.globals.S3Bucket = b
			} else {
				return nil, fmt.Errorf("Must set bucket for s3 backend")
			}
		}
		return newS3Store(a.globals.S3Bucket, "")
	case "S3-KMS":
		if a.globals.S3Bucket == "" {
			if b := os.Getenv("CHAMBER_S3_BUCKET"); b != "" {
				a.globals.S3Bucket = b
			} else {
				return nil, fmt.Errorf("Must set bucket for s3 backend")
			}
		}
		return newS3Store(a.globals.S3Bucket, a.globals.KMSKeyAlias)
	default:
		return nil, fmt.Errorf("invalid backend `%s`", strings.ToUpper(a.globals.Backend))
	}
}

// printRootUsage prints the root usage message
func (a *ChamberApp) printRootUsage() {
	fmt.Fprint(os.Stdout, rootUsage)
}

const rootUsage = `CLI for storing secrets

Usage:
  chamber [command]

Available Commands:
  completion    Generate the autocompletion script for the specified shell
  delete        Delete a secret, including all versions
  env           Print the secrets from the parameter store in a format to export as environment variables
  exec          Executes a command with secrets loaded into the environment
  export        Exports parameters in the specified format
  find          Find the given secret across all services
  help          Help about any command
  history       View the history of a secret
  import        import secrets from json or yaml
  list          List the secrets set for a service
  list-services List services
  read          Read a specific secret from the parameter store
  tag           work with tags on secrets
  version       print version
  write         write a secret

Flags:
  -b, --backend string             Backend to use; AKA $CHAMBER_SECRET_BACKEND
                                   	null: no-op
                                   	ssm: SSM Parameter Store
                                   	secretsmanager: Secrets Manager
                                   	s3: S3; requires --backend-s3-bucket
                                   	s3-kms: S3 using AWS-KMS encryption; requires --backend-s3-bucket and --kms-key-alias set (if you want to write or delete keys). (default "ssm")
      --backend-s3-bucket string   bucket for S3 backend; AKA $CHAMBER_S3_BUCKET
  -h, --help                       help for chamber
      --kms-key-alias string       KMS Key Alias for writing and deleting secrets; AKA $CHAMBER_KMS_KEY_ALIAS. This option is currently only supported for the S3-KMS backend. (default "alias/parameter_store_key")
  -r, --retries int                For SSM or Secrets Manager, the number of retries we'll make before giving up; AKA $CHAMBER_RETRIES (default 10)
      --retry-mode string          For SSM, the model used to retry requests
                                     standard
                                     adaptive (default "standard")
      --verbose                    Print more information to STDERR

Use "chamber [command] --help" for more information about a command.
`

func (a *ChamberApp) printGlobalFlags(w io.Writer) {
	fmt.Fprint(w, globalFlagsUsage)
}

const globalFlagsUsage = `
Global Flags:
  -b, --backend string             Backend to use; AKA $CHAMBER_SECRET_BACKEND
                                   	null: no-op
                                   	ssm: SSM Parameter Store
                                   	secretsmanager: Secrets Manager
                                   	s3: S3; requires --backend-s3-bucket
                                   	s3-kms: S3 using AWS-KMS encryption; requires --backend-s3-bucket and --kms-key-alias set (if you want to write or delete keys). (default "ssm")
      --backend-s3-bucket string   bucket for S3 backend; AKA $CHAMBER_S3_BUCKET
      --kms-key-alias string       KMS Key Alias for writing and deleting secrets; AKA $CHAMBER_KMS_KEY_ALIAS. This option is currently only supported for the S3-KMS backend. (default "alias/parameter_store_key")
  -r, --retries int                For SSM or Secrets Manager, the number of retries we'll make before giving up; AKA $CHAMBER_RETRIES (default 10)
      --retry-mode string          For SSM, the model used to retry requests
                                     standard
                                     adaptive (default "standard")
      --verbose                    Print more information to STDERR
`

func (a *ChamberApp) runHelp(args []string) error {
	if len(args) == 0 {
		a.printRootUsage()
		return nil
	}
	cmd := args[0]
	switch cmd {
	case "write":
		fmt.Fprint(os.Stdout, writeUsage)
	case "read":
		fmt.Fprint(os.Stdout, readUsage)
	case "list":
		fmt.Fprint(os.Stdout, listUsage)
	case "list-services":
		fmt.Fprint(os.Stdout, listServicesUsage)
	case "delete":
		fmt.Fprint(os.Stdout, deleteUsage)
	case "history":
		fmt.Fprint(os.Stdout, historyUsage)
	case "exec":
		fmt.Fprint(os.Stdout, execUsage)
	case "env":
		fmt.Fprint(os.Stdout, envUsage)
	case "export":
		fmt.Fprint(os.Stdout, exportUsage)
	case "import":
		fmt.Fprint(os.Stdout, importUsage)
	case "find":
		fmt.Fprint(os.Stdout, findUsage)
	case "tag":
		fmt.Fprint(os.Stdout, tagUsage)
	case "completion":
		fmt.Fprint(os.Stdout, completionUsage)
	case "version":
		fmt.Fprint(os.Stdout, versionUsage)
	default:
		fmt.Fprintf(os.Stderr, "Error: unknown command %q for \"chamber\"\nRun 'chamber --help' for usage.\n", cmd)
		return fmt.Errorf("unknown command")
	}
	return nil
}
