package main

import (
	"context"
	"fmt"
	"time"
)

// SecretId identifies a secret
type SecretId struct {
	Service string
	Key     string
}

// Secret holds secret data
type Secret struct {
	Value   *string
	Version int
	Created time.Time
	Modified time.Time
	CreatedBy *string
}

// SecretMetaData holds metadata about a secret
type SecretMetaData struct {
	Key         string
	Version     int
	LastModified time.Time
	User        string
}

// HistoryEvent is a record of a version change
type HistoryEvent struct {
	Version  int
	Date     time.Time
	User     string
	Event    string
}

// SecretStore is the interface for secret backends
type SecretStore interface {
	Write(ctx context.Context, id SecretId, value string) error
	Read(ctx context.Context, id SecretId, version int) (Secret, error)
	List(ctx context.Context, service string, includeValues bool) ([]SecretMetaData, error)
	ListRaw(ctx context.Context, service string) (map[string]string, error)
	History(ctx context.Context, id SecretId) ([]HistoryEvent, error)
	Delete(ctx context.Context, id SecretId) error
	ListServices(ctx context.Context, service string, includeSecretNames bool) ([]string, error)
	Find(ctx context.Context, name string, byValue bool) (map[string]string, error) // service -> key or value
	WriteTagsForSecret(ctx context.Context, id SecretId, tags map[string]string) error
	ReadTagsForSecret(ctx context.Context, id SecretId) (map[string]string, error)
	DeleteTagsForSecret(ctx context.Context, id SecretId, tagKeys []string) error
}

