package main

import (
	"bytes"
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"sort"
	"strconv"
	"strings"
	"time"
)

// SSMStore implements SecretStore using AWS SSM Parameter Store
type SSMStore struct {
	retries   int
	retryMode string
	region    string
	creds     awsCreds
}

type awsCreds struct {
	AccessKeyID     string
	SecretAccessKey string
	SessionToken    string
}

func newSSMStore(retries int, retryMode string) (*SSMStore, error) {
	region := getRegion()
	creds, err := getAWSCredentials()
	if err != nil {
		return nil, err
	}
	return &SSMStore{
		retries:   retries,
		retryMode: retryMode,
		region:    region,
		creds:     creds,
	}, nil
}

func getRegion() string {
	if r := os.Getenv("AWS_DEFAULT_REGION"); r != "" {
		return r
	}
	if r := os.Getenv("AWS_REGION"); r != "" {
		return r
	}
	return "us-east-1"
}

func getAWSCredentials() (awsCreds, error) {
	creds := awsCreds{
		AccessKeyID:     os.Getenv("AWS_ACCESS_KEY_ID"),
		SecretAccessKey: os.Getenv("AWS_SECRET_ACCESS_KEY"),
		SessionToken:    os.Getenv("AWS_SESSION_TOKEN"),
	}
	if creds.AccessKeyID != "" && creds.SecretAccessKey != "" {
		return creds, nil
	}
	// Try to get from EC2 IMDS
	imdsToken, err := getIMDSToken()
	if err != nil {
		return awsCreds{}, fmt.Errorf("get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
	}
	roleName, err := getIMDSRole(imdsToken)
	if err != nil {
		return awsCreds{}, fmt.Errorf("get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
	}
	return getIMDSCredentials(imdsToken, roleName)
}

func getIMDSToken() (string, error) {
	client := &http.Client{Timeout: 5 * time.Second}
	req, err := http.NewRequest("PUT", "http://169.254.169.254/latest/api/token", nil)
	if err != nil {
		return "", err
	}
	req.Header.Set("X-aws-ec2-metadata-token-ttl-seconds", "21600")
	resp, err := client.Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", err
	}
	return string(body), nil
}

func getIMDSRole(token string) (string, error) {
	client := &http.Client{Timeout: 5 * time.Second}
	req, err := http.NewRequest("GET", "http://169.254.169.254/latest/meta-data/iam/security-credentials/", nil)
	if err != nil {
		return "", err
	}
	req.Header.Set("X-aws-ec2-metadata-token", token)
	resp, err := client.Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", err
	}
	return strings.TrimSpace(string(body)), nil
}

func getIMDSCredentials(token, role string) (awsCreds, error) {
	client := &http.Client{Timeout: 5 * time.Second}
	url := "http://169.254.169.254/latest/meta-data/iam/security-credentials/" + role
	req, err := http.NewRequest("GET", url, nil)
	if err != nil {
		return awsCreds{}, err
	}
	req.Header.Set("X-aws-ec2-metadata-token", token)
	resp, err := client.Do(req)
	if err != nil {
		return awsCreds{}, err
	}
	defer resp.Body.Close()
	var result struct {
		AccessKeyID     string `json:"AccessKeyId"`
		SecretAccessKey string `json:"SecretAccessKey"`
		Token           string `json:"Token"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&result); err != nil {
		return awsCreds{}, err
	}
	return awsCreds{
		AccessKeyID:     result.AccessKeyID,
		SecretAccessKey: result.SecretAccessKey,
		SessionToken:    result.Token,
	}, nil
}

// AWS Signature V4 implementation
func hmacSHA256(key []byte, data string) []byte {
	h := hmac.New(sha256.New, key)
	h.Write([]byte(data))
	return h.Sum(nil)
}

func sha256Hex(data string) string {
	h := sha256.New()
	h.Write([]byte(data))
	return hex.EncodeToString(h.Sum(nil))
}

func (s *SSMStore) signRequest(req *http.Request, body string, service string) {
	t := time.Now().UTC()
	dateStr := t.Format("20060102")
	dateTimeStr := t.Format("20060102T150405Z")

	// Set required headers
	req.Header.Set("X-Amz-Date", dateTimeStr)
	req.Header.Set("Content-Type", "application/x-amz-json-1.1")
	if s.creds.SessionToken != "" {
		req.Header.Set("X-Amz-Security-Token", s.creds.SessionToken)
	}

	// Create canonical request
	payloadHash := sha256Hex(body)
	req.Header.Set("X-Amz-Target", req.Header.Get("X-Amz-Target"))

	// Sorted headers
	headers := map[string]string{
		"content-type": req.Header.Get("Content-Type"),
		"host":         req.Host,
		"x-amz-date":  dateTimeStr,
		"x-amz-target": req.Header.Get("X-Amz-Target"),
	}
	if s.creds.SessionToken != "" {
		headers["x-amz-security-token"] = s.creds.SessionToken
	}

	headerKeys := make([]string, 0, len(headers))
	for k := range headers {
		headerKeys = append(headerKeys, k)
	}
	sort.Strings(headerKeys)

	canonicalHeaders := ""
	signedHeaders := ""
	for i, k := range headerKeys {
		canonicalHeaders += k + ":" + strings.TrimSpace(headers[k]) + "\n"
		if i > 0 {
			signedHeaders += ";"
		}
		signedHeaders += k
	}

	canonicalURI := req.URL.Path
	if canonicalURI == "" {
		canonicalURI = "/"
	}

	canonicalQueryString := req.URL.RawQuery

	canonicalRequest := strings.Join([]string{
		req.Method,
		canonicalURI,
		canonicalQueryString,
		canonicalHeaders,
		signedHeaders,
		payloadHash,
	}, "\n")

	// Create string to sign
	credentialScope := strings.Join([]string{dateStr, s.region, service, "aws4_request"}, "/")
	stringToSign := strings.Join([]string{
		"AWS4-HMAC-SHA256",
		dateTimeStr,
		credentialScope,
		sha256Hex(canonicalRequest),
	}, "\n")

	// Calculate signature
	signingKey := hmacSHA256(
		hmacSHA256(
			hmacSHA256(
				hmacSHA256(
					[]byte("AWS4"+s.creds.SecretAccessKey),
					dateStr,
				),
				s.region,
			),
			service,
		),
		"aws4_request",
	)
	signature := hex.EncodeToString(hmacSHA256(signingKey, stringToSign))

	// Set Authorization header
	auth := fmt.Sprintf(
		"AWS4-HMAC-SHA256 Credential=%s/%s, SignedHeaders=%s, Signature=%s",
		s.creds.AccessKeyID, credentialScope, signedHeaders, signature,
	)
	req.Header.Set("Authorization", auth)
}

func (s *SSMStore) ssmRequest(ctx context.Context, action string, payload interface{}) ([]byte, error) {
	body, err := json.Marshal(payload)
	if err != nil {
		return nil, err
	}

	url := fmt.Sprintf("https://ssm.%s.amazonaws.com/", s.region)
	req, err := http.NewRequestWithContext(ctx, "POST", url, bytes.NewReader(body))
	if err != nil {
		return nil, err
	}
	req.Host = fmt.Sprintf("ssm.%s.amazonaws.com", s.region)
	req.Header.Set("X-Amz-Target", "AmazonSSM."+action)

	s.signRequest(req, string(body), "ssm")

	client := &http.Client{Timeout: 30 * time.Second}
	resp, err := client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("operation error SSM: %s, %v", action, err)
	}
	defer resp.Body.Close()
	respBody, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, err
	}

	if resp.StatusCode != 200 {
		var errResp struct {
			Code    string `json:"__type"`
			Message string `json:"message"`
		}
		if jerr := json.Unmarshal(respBody, &errResp); jerr == nil && errResp.Code != "" {
			return nil, fmt.Errorf("operation error SSM: %s, %s: %s", action, errResp.Code, errResp.Message)
		}
		return nil, fmt.Errorf("operation error SSM: %s, HTTP %d", action, resp.StatusCode)
	}

	return respBody, nil
}

func normalizeKey(key string) string {
	return strings.ToLower(key)
}

func (s *SSMStore) parameterPath(id SecretId) string {
	return fmt.Sprintf("/%s/%s", id.Service, normalizeKey(id.Key))
}

func (s *SSMStore) Write(ctx context.Context, id SecretId, value string) error {
	path := s.parameterPath(id)
	payload := map[string]interface{}{
		"Name":      path,
		"Value":     value,
		"Type":      "SecureString",
		"Overwrite": true,
	}
	_, err := s.ssmRequest(ctx, "PutParameter", payload)
	return err
}

func (s *SSMStore) Read(ctx context.Context, id SecretId, version int) (Secret, error) {
	path := s.parameterPath(id)
	name := path
	if version > 0 {
		name = fmt.Sprintf("%s:%d", path, version)
	}
	payload := map[string]interface{}{
		"Name":           name,
		"WithDecryption": true,
	}
	data, err := s.ssmRequest(ctx, "GetParameter", payload)
	if err != nil {
		return Secret{}, err
	}
	var result struct {
		Parameter struct {
			Value            string `json:"Value"`
			Version          int64  `json:"Version"`
			LastModifiedDate float64 `json:"LastModifiedDate"`
		} `json:"Parameter"`
	}
	if err := json.Unmarshal(data, &result); err != nil {
		return Secret{}, err
	}
	v := result.Parameter.Value
	modTime := time.Unix(int64(result.Parameter.LastModifiedDate), 0)
	ver := int(result.Parameter.Version)
	return Secret{
		Value:    &v,
		Version:  ver,
		Modified: modTime,
	}, nil
}

func (s *SSMStore) List(ctx context.Context, service string, includeValues bool) ([]SecretMetaData, error) {
	prefix := "/" + service + "/"
	var results []SecretMetaData
	var nextToken *string

	for {
		payload := map[string]interface{}{
			"ParameterFilters": []map[string]interface{}{
				{
					"Key":    "Path",
					"Option": "OneLevel",
					"Values": []string{prefix[:len(prefix)-1]},
				},
			},
			"MaxResults": 50,
		}
		if nextToken != nil {
			payload["NextToken"] = *nextToken
		}

		data, err := s.ssmRequest(ctx, "DescribeParameters", payload)
		if err != nil {
			return nil, err
		}
		var resp struct {
			Parameters []struct {
				Name             string  `json:"Name"`
				Version          int64   `json:"Version"`
				LastModifiedDate float64 `json:"LastModifiedDate"`
				LastModifiedUser string  `json:"LastModifiedUser"`
			} `json:"Parameters"`
			NextToken *string `json:"NextToken"`
		}
		if err := json.Unmarshal(data, &resp); err != nil {
			return nil, err
		}
		for _, p := range resp.Parameters {
			key := strings.TrimPrefix(p.Name, prefix)
			modTime := time.Unix(int64(p.LastModifiedDate), 0)
			results = append(results, SecretMetaData{
				Key:          key,
				Version:      int(p.Version),
				LastModified: modTime,
				User:         p.LastModifiedUser,
			})
		}
		nextToken = resp.NextToken
		if nextToken == nil {
			break
		}
	}
	return results, nil
}

func (s *SSMStore) ListRaw(ctx context.Context, service string) (map[string]string, error) {
	path := "/" + service
	result := make(map[string]string)
	var nextToken *string

	for {
		payload := map[string]interface{}{
			"Path":           path,
			"WithDecryption": true,
			"Recursive":      false,
		}
		if nextToken != nil {
			payload["NextToken"] = *nextToken
		}

		data, err := s.ssmRequest(ctx, "GetParametersByPath", payload)
		if err != nil {
			return nil, err
		}
		var resp struct {
			Parameters []struct {
				Name  string `json:"Name"`
				Value string `json:"Value"`
			} `json:"Parameters"`
			NextToken *string `json:"NextToken"`
		}
		if err := json.Unmarshal(data, &resp); err != nil {
			return nil, err
		}
		prefix := path + "/"
		for _, p := range resp.Parameters {
			key := strings.TrimPrefix(p.Name, prefix)
			result[key] = p.Value
		}
		nextToken = resp.NextToken
		if nextToken == nil {
			break
		}
	}
	return result, nil
}

