func (s *SecretsManagerStore) secretName(id SecretId) string {
	return id.Service + "/" + strings.ToLower(id.Key)
}

func (s *SecretsManagerStore) Write(ctx context.Context, id SecretId, value string) error {
	name := s.secretName(id)
	// Try to create first, then update if exists
	createPayload := map[string]interface{}{
		"Name":         name,
		"SecretString": value,
	}
	_, err := s.smRequest(ctx, "CreateSecret", createPayload)
	if err != nil {
		if strings.Contains(err.Error(), "ResourceExistsException") {
			updatePayload := map[string]interface{}{
				"SecretId":     name,
				"SecretString": value,
			}
			_, err = s.smRequest(ctx, "PutSecretValue", updatePayload)
		}
	}
	return err
}

func (s *SecretsManagerStore) Read(ctx context.Context, id SecretId, version int) (Secret, error) {
	name := s.secretName(id)
	payload := map[string]interface{}{
		"SecretId": name,
	}
	if version > 0 {
		payload["VersionId"] = fmt.Sprintf("%d", version)
	}
	data, err := s.smRequest(ctx, "GetSecretValue", payload)
	if err != nil {
		return Secret{}, err
	}
	var result struct {
		SecretString string  `json:"SecretString"`
		VersionId    string  `json:"VersionId"`
		CreatedDate  float64 `json:"CreatedDate"`
	}
	if err := json.Unmarshal(data, &result); err != nil {
		return Secret{}, err
	}
	v := result.SecretString
	created := time.Unix(int64(result.CreatedDate), 0)
	return Secret{
		Value:   &v,
		Created: created,
	}, nil
}

func (s *SecretsManagerStore) List(ctx context.Context, service string, includeValues bool) ([]SecretMetaData, error) {
