	var results []SecretMetaData
	var nextToken *string

	for {
		payload := map[string]interface{}{
			"Filters": []map[string]interface{}{
				{
					"Key":    "name",
					"Values": []string{prefix},
				},
			},
			"MaxResults": 100,
		}
		if nextToken != nil {
			payload["NextToken"] = *nextToken
		}
		data, err := s.smRequest(ctx, "ListSecrets", payload)
		if err != nil {
			return nil, err
		}
		var resp struct {
			SecretList []struct {
				Name             string  `json:"Name"`
				LastChangedDate  float64 `json:"LastChangedDate"`
			} `json:"SecretList"`
			NextToken *string `json:"NextToken"`
		}
		if err := json.Unmarshal(data, &resp); err != nil {
			return nil, err
		}
		for _, sec := range resp.SecretList {
			key := strings.TrimPrefix(sec.Name, prefix)
			modTime := time.Unix(int64(sec.LastChangedDate), 0)
			results = append(results, SecretMetaData{
				Key:          key,
				LastModified: modTime,
			})
		}
		nextToken = resp.NextToken
		if nextToken == nil {
			break
