func newS3Store(bucket, kmsKeyAlias string) (*S3Store, error) {
	region := getRegion()
	creds, err := getAWSCredentials()
	if err != nil {
		return nil, err
	}
	return &S3Store{
		bucket:      bucket,
		kmsKeyAlias: kmsKeyAlias,
		region:      region,
		creds:       creds,
	}, nil
}

func (s *S3Store) objectKey(id SecretId) string {
	return id.Service + "/" + strings.ToLower(id.Key)
}

func (s *S3Store) s3Request(ctx context.Context, method, path string, body []byte, headers map[string]string) ([]byte, int, error) {
	host := fmt.Sprintf("%s.s3.%s.amazonaws.com", s.bucket, s.region)
	url := fmt.Sprintf("https://%s%s", host, path)

	var bodyReader io.Reader
	if body != nil {
		bodyReader = bytes.NewReader(body)
	}

	req, err := http.NewRequestWithContext(ctx, method, url, bodyReader)
	if err != nil {
		return nil, 0, err
	}
	req.Host = host
	for k, v := range headers {
		req.Header.Set(k, v)
	}

	// Sign the request
	ssmStore := &SSMStore{creds: s.creds, region: s.region}
	bodyStr := ""
	if body != nil {
		bodyStr = string(body)
	}
	ssmStore.signRequest(req, bodyStr, "s3")

	client := &http.Client{Timeout: 30 * time.Second}
	resp, err := client.Do(req)
	if err != nil {
		return nil, 0, fmt.Errorf("operation error S3: %s, %v", method, err)
	}
	defer resp.Body.Close()
	respBody, err := io.ReadAll(resp.Body)
	return respBody, resp.StatusCode, err
}

type s3SecretData struct {
	Value   string    `json:"value"`
	Version int       `json:"version"`
	Created time.Time `json:"created"`
}

func (s *S3Store) Write(ctx context.Context, id SecretId, value string) error {
	// Read current version if exists
	current, err := s.Read(ctx, id, 0)
	version := 1
	if err == nil {
		version = current.Version + 1
	}

	key := s.objectKey(id)
	data := s3SecretData{
		Value:   value,
		Version: version,
		Created: time.Now(),
	}
	body, err := json.Marshal(data)
	if err != nil {
		return err
	}

	headers := map[string]string{
		"Content-Type": "application/json",
	}
	if s.kmsKeyAlias != "" {
		headers["x-amz-server-side-encryption"] = "aws:kms"
		headers["x-amz-server-side-encryption-aws-kms-key-id"] = s.kmsKeyAlias
	}

	respBody, code, err := s.s3Request(ctx, "PUT", "/"+key, body, headers)
	if err != nil {
		return err
	}
	if code != 200 {
		return fmt.Errorf("S3 PUT failed: %d %s", code, string(respBody))
	}
	return nil
}

func (s *S3Store) Read(ctx context.Context, id SecretId, version int) (Secret, error) {
	key := s.objectKey(id)
	respBody, code, err := s.s3Request(ctx, "GET", "/"+key, nil, nil)
	if err != nil {
		return Secret{}, fmt.Errorf("operation error S3: GetObject, %v", err)
	}
	if code == 404 {
		return Secret{}, fmt.Errorf("secret not found: %s/%s", id.Service, id.Key)
	}
	if code != 200 {
		return Secret{}, fmt.Errorf("S3 GET failed: %d", code)
	}
	var data s3SecretData
	if err := json.Unmarshal(respBody, &data); err != nil {
		return Secret{}, err
	}
	v := data.Value
	return Secret{
		Value:   &v,
		Version: data.Version,
		Created: data.Created,
	}, nil
}

func (s *S3Store) List(ctx context.Context, service string, includeValues bool) ([]SecretMetaData, error) {
	prefix := service + "/"
	respBody, code, err := s.s3Request(ctx, "GET", "/?list-type=2&prefix="+prefix, nil, nil)
	if err != nil {
		return nil, fmt.Errorf("operation error S3: ListObjectsV2, %v", err)
	}
	if code != 200 {
		return nil, fmt.Errorf("S3 List failed: %d %s", code, string(respBody))
	}

	// Parse XML response
	var results []SecretMetaData
	lines := strings.Split(string(respBody), "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "<Key>") {
			key := strings.TrimSuffix(strings.TrimPrefix(line, "<Key>"), "</Key>")
			key = strings.TrimPrefix(key, prefix)
			if key == "" {
				continue
			}
			results = append(results, SecretMetaData{Key: key})
		}
	}
	sort.Slice(results, func(i, j int) bool {
		return results[i].Key < results[j].Key
	})
	return results, nil
}

