func (s *S3Store) s3Request(ctx context.Context, method, path string, body []byte, headers map[string]string) ([]byte, int, error) {
	host := fmt.Sprintf("%s.s3.%s.amazonaws.com", s.bucket, s.region)
	url := fmt.Sprintf("https://%s%s", host, path)

	var bodyReader io.Reader
	if body != nil {
