// runVersion prints the version
func (a *ChamberApp) runVersion(args []string) error {
	for _, arg := range args {
		if arg == "--help" || arg == "-h" {
			fmt.Fprint(os.Stdout, versionUsage)
			return nil
		}
	}
	fmt.Println("chamber dev")
	return nil
}

const versionUsage = `print version

Usage:
  chamber version [flags]

Flags:
  -h, --help   help for version

` + globalFlagsUsage[1:] // trim leading newline

// runWrite writes a secret
func (a *ChamberApp) runWrite(args []string) error {
	// Parse flags
	singleline := false
	skipUnchanged := false
	tags := map[string]string{}

	positional := []string{}
	i := 0
	seenDashDash := false
	for i < len(args) {
		arg := args[i]
		if seenDashDash {
			positional = append(positional, arg)
			i++
			continue
		}
		switch arg {
		case "--help", "-h":
			fmt.Fprint(os.Stdout, writeUsage)
			return nil
		case "-s", "--singleline":
			singleline = true
		case "--skip-unchanged":
			skipUnchanged = true
		case "-t", "--tags":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "Error: flag needs an argument: '--tags'\n")
				fmt.Fprint(os.Stderr, writeUsage)
				return fmt.Errorf("flag error")
			}
			parseTags(args[i], tags)
		case "--":
			seenDashDash = true
		default:
			if strings.HasPrefix(arg, "--tags=") {
				parseTags(arg[7:], tags)
			} else if strings.HasPrefix(arg, "-t=") {
				parseTags(arg[3:], tags)
			} else if strings.HasPrefix(arg, "-") {
				fmt.Fprintf(os.Stderr, "Error: unknown flag: '%s'\n", arg)
				fmt.Fprint(os.Stderr, writeUsage)
				return fmt.Errorf("unknown flag")
			} else {
				positional = append(positional, arg)
			}
		}
		i++
	}

	if len(positional) != 3 {
		fmt.Fprintf(os.Stderr, "Error: accepts 3 arg(s), received %d\n", len(positional))
		fmt.Fprint(os.Stderr, writeUsage)
		return fmt.Errorf("wrong number of args")
	}

	service := positional[0]
	key := positional[1]
	valueArg := positional[2]

	var value string
	if valueArg == "-" {
		// Read from stdin
		if singleline {
			reader := bufio.NewReader(os.Stdin)
			line, err := reader.ReadString('\n')
			if err != nil && err != io.EOF {
				fmt.Fprintf(os.Stderr, "Error: Failed to read from stdin: %v\n", err)
				return err
			}
			value = strings.TrimSuffix(line, "\n")
		} else {
			data, err := io.ReadAll(os.Stdin)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: Failed to read from stdin: %v\n", err)
				return err
			}
			value = string(data)
		}
	} else {
		value = valueArg
	}

	store, err := a.getStore()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: Failed to get secret store: %v\n", err)
		return err
	}

	id := SecretId{Service: service, Key: key}

	if skipUnchanged {
		existing, err := store.Read(context.Background(), id, 0)
		if err == nil && existing.Value != nil && *existing.Value == value {
			return nil
		}
	}

	if err := store.Write(context.Background(), id, value); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return err
	}

	// Write tags if specified
	if len(tags) > 0 {
		if err := store.WriteTagsForSecret(context.Background(), id, tags); err != nil {
			// Just log the error, don't fail
			if a.globals.Verbose {
				fmt.Fprintf(os.Stderr, "Warning: Failed to write tags: %v\n", err)
			}
		}
	}

	return nil
}

func parseTags(s string, tags map[string]string) {
	parts := strings.Split(s, ",")
	for _, part := range parts {
		kv := strings.SplitN(part, "=", 2)
		if len(kv) == 2 {
			tags[kv[0]] = kv[1]
		}
	}
}

// runRead reads a secret
func (a *ChamberApp) runRead(args []string) error {
	quiet := false
	version := -1

	positional := []string{}
	i := 0
	for i < len(args) {
		arg := args[i]
		switch arg {
		case "--help", "-h":
			fmt.Fprint(os.Stdout, readUsage)
			return nil
		case "-q", "--quiet":
			quiet = true
		case "-v", "--version":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "Error: flag needs an argument: '--version'\n")
				return fmt.Errorf("flag error")
			}
			n, err := strconv.Atoi(args[i])
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: invalid version: %v\n", err)
				return err
			}
			version = n
		default:
			if strings.HasPrefix(arg, "--version=") {
				n, err := strconv.Atoi(arg[10:])
				if err == nil {
					version = n
				}
			} else if strings.HasPrefix(arg, "-v=") {
				n, err := strconv.Atoi(arg[3:])
				if err == nil {
					version = n
				}
			} else if strings.HasPrefix(arg, "-") {
				fmt.Fprintf(os.Stderr, "Error: unknown flag: '%s'\n", arg)
				return fmt.Errorf("unknown flag")
			} else {
				positional = append(positional, arg)
			}
		}
		i++
	}

	if len(positional) != 2 {
		fmt.Fprintf(os.Stderr, "Error: accepts 2 arg(s), received %d\n", len(positional))
		fmt.Fprint(os.Stderr, readUsage)
		return fmt.Errorf("wrong number of args")
	}

	service := positional[0]
	key := positional[1]

	store, err := a.getStore()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: Failed to get secret store: %v\n", err)
		return err
	}

	id := SecretId{Service: service, Key: key}
	secret, err := store.Read(context.Background(), id, version)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: Failed to read: %v\n", err)
		return err
	}

	if quiet {
		if secret.Value != nil {
			fmt.Print(*secret.Value)
		}
	} else {
		// Print formatted output
		modifiedStr := ""
		if !secret.Modified.IsZero() {
			modifiedStr = secret.Modified.Format(time.RFC3339)
		}
		fmt.Printf("Key\t\tVersion\t\tLastModified\t\tUser\n")
		userStr := ""
		if secret.CreatedBy != nil {
			userStr = *secret.CreatedBy
		}
		valueStr := ""
		if secret.Value != nil {
			valueStr = *secret.Value
		}
		fmt.Printf("%s\t\t%d\t\t%s\t\t%s\n\nValue: %s\n", strings.ToLower(key), secret.Version, modifiedStr, userStr, valueStr)
	}

	return nil
}

// runList lists secrets for a service
func (a *ChamberApp) runList(args []string) error {
	expand := false
	sortByTime := false
	sortByUser := false
	sortByVersion := false

	positional := []string{}
	i := 0
	for i < len(args) {
		arg := args[i]
		switch arg {
		case "--help", "-h":
			fmt.Fprint(os.Stdout, listUsage)
			return nil
		case "-e", "--expand":
			expand = true
		case "-t", "--time":
			sortByTime = true
		case "-u", "--user":
			sortByUser = true
		case "-v", "--version":
			sortByVersion = true
		default:
			if strings.HasPrefix(arg, "-") {
				fmt.Fprintf(os.Stderr, "Error: unknown flag: '%s'\n", arg)
				return fmt.Errorf("unknown flag")
			}
			positional = append(positional, arg)
		}
		i++
	}

	if len(positional) != 1 {
		fmt.Fprintf(os.Stderr, "Error: accepts 1 arg(s), received %d\n", len(positional))
		fmt.Fprint(os.Stderr, listUsage)
		return fmt.Errorf("wrong number of args")
	}

	service := positional[0]

	store, err := a.getStore()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: Failed to get secret store: %v\n", err)
		return err
	}

	secrets, err := store.List(context.Background(), service, expand)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: Failed to list store contents: %v\n", err)
		return err
	}

	// Sort
	if sortByTime {
		sort.Slice(secrets, func(i, j int) bool {
			return secrets[i].LastModified.Before(secrets[j].LastModified)
		})
	} else if sortByUser {
		sort.Slice(secrets, func(i, j int) bool {
			return secrets[i].User < secrets[j].User
		})
	} else if sortByVersion {
		sort.Slice(secrets, func(i, j int) bool {
			return secrets[i].Version < secrets[j].Version
		})
	} else {
		sort.Slice(secrets, func(i, j int) bool {
			return secrets[i].Key < secrets[j].Key
		})
	}

	if expand {
		fmt.Printf("Key\tVersion\t\tLastModified\tUser\tValue\n")
		for _, s := range secrets {
			modStr := s.LastModified.Format(time.RFC3339)
			valueStr := ""
			if expand {
				// Need to fetch value
				secret, rerr := store.Read(context.Background(), SecretId{Service: service, Key: s.Key}, 0)
				if rerr == nil && secret.Value != nil {
					valueStr = *secret.Value
				}
			}
			fmt.Printf("%s\t%d\t\t%s\t%s\t%s\n", s.Key, s.Version, modStr, s.User, valueStr)
		}
	} else {
		fmt.Printf("Key\tVersion\t\tLastModified\tUser\n")
		for _, s := range secrets {
			modStr := s.LastModified.Format(time.RFC3339)
			fmt.Printf("%s\t%d\t\t%s\t%s\n", s.Key, s.Version, modStr, s.User)
		}
	}

	return nil
}

