	positional := []string{}
	i := 0
	for i < len(args) {
		arg := args[i]
		switch arg {
		case "--help", "-h":
			fmt.Fprint(os.Stdout, listUsage)
			return nil
		case "-e", "--expand":
			expand = true
		case "-t", "--time":
			sortByTime = true
		case "-u", "--user":
			sortByUser = true
		case "-v", "--version":
			sortByVersion = true
		default:
			if strings.HasPrefix(arg, "-") {
				fmt.Fprintf(os.Stderr, "Error: unknown flag: '%s'\n", arg)
				return fmt.Errorf("unknown flag")
			}
			positional = append(positional, arg)
		}
		i++
	}

	if len(positional) != 1 {
		fmt.Fprintf(os.Stderr, "Error: accepts 1 arg(s), received %d\n", len(positional))
		fmt.Fprint(os.Stderr, listUsage)
		return fmt.Errorf("wrong number of args")
	}

	service := positional[0]

	store, err := a.getStore()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: Failed to get secret store: %v\n", err)
		return err
	}

	secrets, err := store.List(context.Background(), service, expand)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: Failed to list store contents: %v\n", err)
		return err
	}

	// Sort
	if sortByTime {
		sort.Slice(secrets, func(i, j int) bool {
			return secrets[i].LastModified.Before(secrets[j].LastModified)
		})
	} else if sortByUser {
		sort.Slice(secrets, func(i, j int) bool {
			return secrets[i].User < secrets[j].User
		})
	} else if sortByVersion {
		sort.Slice(secrets, func(i, j int) bool {
			return secrets[i].Version < secrets[j].Version
		})
	} else {
		sort.Slice(secrets, func(i, j int) bool {
			return secrets[i].Key < secrets[j].Key
		})
	}

	if expand {
		fmt.Printf("Key\tVersion\t\tLastModified\tUser\tValue\n")
		for _, s := range secrets {
			modStr := s.LastModified.Format(time.RFC3339)
			valueStr := ""
			if expand {
				// Need to fetch value
				secret, rerr := store.Read(context.Background(), SecretId{Service: service, Key: s.Key}, 0)
				if rerr == nil && secret.Value != nil {
					valueStr = *secret.Value
				}
			}
			fmt.Printf("%s\t%d\t\t%s\t%s\t%s\n", s.Key, s.Version, modStr, s.User, valueStr)
		}
	} else {
		fmt.Printf("Key\tVersion\t\tLastModified\tUser\n")
		for _, s := range secrets {
			modStr := s.LastModified.Format(time.RFC3339)
			fmt.Printf("%s\t%d\t\t%s\t%s\n", s.Key, s.Version, modStr, s.User)
		}
	}

	return nil
}

