		fmt.Fprint(os.Stderr, tagDeleteUsage)
		return fmt.Errorf("wrong number of args")
	}

	service := positional[0]
	key := positional[1]
	tagKeys := positional[2:]

	store, err := a.getStore()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: Failed to get secret store: %v\n", err)
