	}

	id := SecretId{Service: service, Key: key}
	if err := store.DeleteTagsForSecret(context.Background(), id, tagKeys); err != nil {
		fmt.Fprintf(os.Stderr, "Error: Failed to delete tags: %v\n", err)
		return err
	}

	return nil
}

