// runExec executes a command with secrets loaded into the environment
func (a *ChamberApp) runExec(args []string) error {
	pristine := false
	strict := false
	strictValue := "chamberme"

	// Find the -- separator
	sepIdx := -1
	for idx, arg := range args {
		if arg == "--" {
			sepIdx = idx
			break
		}
	}

	var cmdArgs []string
	var flagArgs []string
	if sepIdx >= 0 {
		flagArgs = args[:sepIdx]
		cmdArgs = args[sepIdx+1:]
	} else {
		flagArgs = args
	}

	services := []string{}
	i := 0
	for i < len(flagArgs) {
		arg := flagArgs[i]
		switch arg {
		case "--help", "-h":
			fmt.Fprint(os.Stdout, execUsage)
			return nil
		case "--pristine":
			pristine = true
		case "--strict":
			strict = true
		case "--strict-value":
			i++
			if i >= len(flagArgs) {
				fmt.Fprintf(os.Stderr, "Error: flag needs an argument: '--strict-value'\n")
				return fmt.Errorf("flag error")
			}
			strictValue = flagArgs[i]
		default:
			if strings.HasPrefix(arg, "--strict-value=") {
				strictValue = arg[15:]
			} else if strings.HasPrefix(arg, "-") {
				fmt.Fprintf(os.Stderr, "Error: unknown flag: '%s'\n", arg)
				return fmt.Errorf("unknown flag")
			} else {
				services = append(services, arg)
			}
		}
		i++
	}

	if len(services) == 0 {
		fmt.Fprintf(os.Stderr, "Error: at least one service must be specified: requires at least 1 arg(s), only received 0\n")
		fmt.Fprint(os.Stderr, execUsage)
		return fmt.Errorf("no service")
	}

	if len(cmdArgs) == 0 {
		fmt.Fprintf(os.Stderr, "Error: must specify command to run. See usage: requires at least 1 arg(s), only received 0\n")
		fmt.Fprint(os.Stderr, execUsage)
		return fmt.Errorf("no command")
	}

	store, err := a.getStore()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: Failed to get secret store: %v\n", err)
		return err
	}

	// Collect all secrets
	allSecrets := make(map[string]string)
	for _, service := range services {
		raw, err := store.ListRaw(context.Background(), service)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: Failed to list secrets: %v\n", err)
			return err
		}
		for k, v := range raw {
			allSecrets[strings.ToUpper(k)] = v
		}
	}

	// Build environment
	var env []string

	if strict {
		// Check env vars with strictValue
		currentEnv := os.Environ()
		for _, e := range currentEnv {
			parts := strings.SplitN(e, "=", 2)
			if len(parts) == 2 && parts[1] == strictValue {
				// This env var must be in secrets
				k := parts[0]
				if _, ok := allSecrets[k]; !ok {
					fmt.Fprintf(os.Stderr, "chamber: extra unfilled env var %s\n", k)
					os.Exit(1)
				}
			}
		}
	}

	if pristine {
		// Only use secrets
		for k, v := range allSecrets {
			env = append(env, k+"="+v)
		}
	} else {
		// Start with current environment
		env = os.Environ()
		// Override with secrets
		secretKeys := make(map[string]bool)
		for k := range allSecrets {
			secretKeys[k] = true
		}
		// Remove any env vars that will be overridden
		newEnv := []string{}
		for _, e := range env {
			parts := strings.SplitN(e, "=", 2)
			if len(parts) == 2 {
				if !secretKeys[parts[0]] {
					newEnv = append(newEnv, e)
				}
			} else {
				newEnv = append(newEnv, e)
			}
		}
		env = newEnv
		for k, v := range allSecrets {
			env = append(env, k+"="+v)
		}
	}

	// Execute command
	cmdPath, err := exec.LookPath(cmdArgs[0])
	if err != nil {
		cmdPath = cmdArgs[0]
	}

	execArgs := append([]string{cmdPath}, cmdArgs[1:]...)

	if execErr := syscall.Exec(cmdPath, execArgs, env); execErr != nil {
		// syscall.Exec failed, try with exec.Command
		cmd := exec.Command(cmdArgs[0], cmdArgs[1:]...)
		cmd.Env = env
		cmd.Stdin = os.Stdin
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		if runErr := cmd.Run(); runErr != nil {
			if exitErr, ok := runErr.(*exec.ExitError); ok {
				os.Exit(exitErr.ExitCode())
			}
			return runErr
		}
	}
	return nil
}

// runEnv prints secrets as export statements
func (a *ChamberApp) runEnv(args []string) error {
	preserveCase := false
	escapeStrings := false

	positional := []string{}
	i := 0
	for i < len(args) {
		arg := args[i]
		switch arg {
		case "--help", "-h":
			fmt.Fprint(os.Stdout, envUsage)
			return nil
		case "-p", "--preserve-case":
			preserveCase = true
		case "-e", "--escape-strings":
			escapeStrings = true
		default:
			if strings.HasPrefix(arg, "-") {
				fmt.Fprintf(os.Stderr, "Error: unknown flag: '%s'\n", arg)
				return fmt.Errorf("unknown flag")
			}
			positional = append(positional, arg)
		}
		i++
	}

	if len(positional) != 1 {
		fmt.Fprintf(os.Stderr, "Error: accepts 1 arg(s), received %d\n", len(positional))
		fmt.Fprint(os.Stderr, envUsage)
		return fmt.Errorf("wrong number of args")
	}

	service := positional[0]

	store, err := a.getStore()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: Failed to get secret store: %v\n", err)
		return err
	}

	raw, err := store.ListRaw(context.Background(), service)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: Failed to list secrets: %v\n", err)
		return err
	}

	// Sort keys for consistent output
	keys := make([]string, 0, len(raw))
	for k := range raw {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	for _, k := range keys {
		v := raw[k]
		envKey := k
		if !preserveCase {
			envKey = strings.ToUpper(k)
		}
		if escapeStrings {
			v = escapeEnvValue(v)
		}
		fmt.Printf("export %s=%q\n", envKey, v)
	}

	return nil
}

func escapeEnvValue(s string) string {
	return strings.ReplaceAll(strings.ReplaceAll(s, `\`, `\\`), `"`, `\"`)
}

// runExport exports parameters in specified format
func (a *ChamberApp) runExport(args []string) error {
	format := "json"
	outputFile := ""

	positional := []string{}
	i := 0
	for i < len(args) {
		arg := args[i]
		switch arg {
		case "--help", "-h":
			fmt.Fprint(os.Stdout, exportUsage)
			return nil
		case "-f", "--format":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "Error: flag needs an argument: '--format'\n")
				return fmt.Errorf("flag error")
			}
			format = args[i]
		case "-o", "--output-file":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "Error: flag needs an argument: '--output-file'\n")
				return fmt.Errorf("flag error")
			}
			outputFile = args[i]
		default:
			if strings.HasPrefix(arg, "--format=") {
				format = arg[9:]
			} else if strings.HasPrefix(arg, "-f=") {
				format = arg[3:]
			} else if strings.HasPrefix(arg, "--output-file=") {
				outputFile = arg[14:]
			} else if strings.HasPrefix(arg, "-o=") {
				outputFile = arg[3:]
			} else if strings.HasPrefix(arg, "-") {
				fmt.Fprintf(os.Stderr, "Error: unknown flag: '%s'\n", arg)
				return fmt.Errorf("unknown flag")
			} else {
				positional = append(positional, arg)
			}
		}
		i++
	}

	if len(positional) < 1 {
		fmt.Fprintf(os.Stderr, "Error: requires at least 1 arg(s), only received %d\n", len(positional))
		fmt.Fprint(os.Stderr, exportUsage)
		return fmt.Errorf("wrong number of args")
	}

	store, err := a.getStore()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: Failed to get secret store: %v\n", err)
		return err
	}

	// Collect secrets from all services
	allSecrets := make(map[string]string)
	for _, service := range positional {
		raw, err := store.ListRaw(context.Background(), service)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: Failed to list store contents: %v\n", err)
			return err
		}
		for k, v := range raw {
			allSecrets[k] = v
		}
	}

	var output []byte
	var writeErr error

	switch strings.ToLower(format) {
	case "json":
		output, writeErr = exportJSON(allSecrets)
	case "yaml":
		output, writeErr = exportYAML(allSecrets)
	case "java-properties":
		output, writeErr = exportJavaProperties(allSecrets)
	case "csv":
		output, writeErr = exportCSV(allSecrets)
	case "tsv":
		output, writeErr = exportTSV(allSecrets)
	case "dotenv":
		output, writeErr = exportDotenv(allSecrets)
	case "tfvars":
		output, writeErr = exportTFVars(allSecrets)
	default:
		fmt.Fprintf(os.Stderr, "Error: Unable to export parameters: Unsupported export format: %s\n", format)
		return fmt.Errorf("unsupported format")
	}

	if writeErr != nil {
		fmt.Fprintf(os.Stderr, "Error: Failed to export: %v\n", writeErr)
		return writeErr
	}

	var w io.Writer = os.Stdout
	if outputFile != "" {
		f, err := os.Create(outputFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: Failed to open output file: %v\n", err)
			return err
		}
		defer f.Close()
		w = f
	}

	_, err = w.Write(output)
	return err
}

func exportJSON(secrets map[string]string) ([]byte, error) {
	if len(secrets) == 0 {
		return []byte("{}\n"), nil
	}
	// Sort keys
	keys := sortedKeys(secrets)
	ordered := make(map[string]string)
	for _, k := range keys {
		ordered[k] = secrets[k]
	}
	b, err := json.MarshalIndent(ordered, "", "  ")
	if err != nil {
		return nil, err
	}
	return append(b, '\n'), nil
}

func exportYAML(secrets map[string]string) ([]byte, error) {
	if len(secrets) == 0 {
		return []byte("{}\n"), nil
	}
	keys := sortedKeys(secrets)
	var sb strings.Builder
	for _, k := range keys {
		v := secrets[k]
		// Quote if necessary
		if strings.ContainsAny(v, ":#{}[]|>&*!,'\"\\@`") || strings.Contains(v, "\n") {
			sb.WriteString(fmt.Sprintf("%s: %q\n", k, v))
		} else {
			sb.WriteString(fmt.Sprintf("%s: %s\n", k, v))
		}
	}
	return []byte(sb.String()), nil
}

func exportJavaProperties(secrets map[string]string) ([]byte, error) {
	keys := sortedKeys(secrets)
	var sb strings.Builder
	for _, k := range keys {
		sb.WriteString(fmt.Sprintf("%s=%s\n", k, secrets[k]))
	}
	return []byte(sb.String()), nil
}

func exportCSV(secrets map[string]string) ([]byte, error) {
	var buf bytes.Buffer
	w := csv.NewWriter(&buf)
	keys := sortedKeys(secrets)
	for _, k := range keys {
		if err := w.Write([]string{k, secrets[k]}); err != nil {
			return nil, err
		}
	}
	w.Flush()
	return buf.Bytes(), nil
}

type tsvWriter struct {
	w io.Writer
}

func exportTSV(secrets map[string]string) ([]byte, error) {
	var sb strings.Builder
	keys := sortedKeys(secrets)
	for _, k := range keys {
		sb.WriteString(k + "\t" + secrets[k] + "\n")
	}
	return []byte(sb.String()), nil
}

func exportDotenv(secrets map[string]string) ([]byte, error) {
	keys := sortedKeys(secrets)
	var sb strings.Builder
	for _, k := range keys {
		sb.WriteString(fmt.Sprintf("%s=%q\n", k, secrets[k]))
	}
	return []byte(sb.String()), nil
}

func exportTFVars(secrets map[string]string) ([]byte, error) {
	keys := sortedKeys(secrets)
	var sb strings.Builder
	for _, k := range keys {
		sb.WriteString(fmt.Sprintf("%s = %q\n", k, secrets[k]))
	}
	return []byte(sb.String()), nil
}

func sortedKeys(m map[string]string) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

// runImport imports secrets from json/yaml
func (a *ChamberApp) runImport(args []string) error {
	normalizeKeys := false

	positional := []string{}
	i := 0
	for i < len(args) {
		arg := args[i]
		switch arg {
		case "--help", "-h":
			fmt.Fprint(os.Stdout, importUsage)
			return nil
		case "--normalize-keys":
			normalizeKeys = true
		default:
			if strings.HasPrefix(arg, "-") {
				fmt.Fprintf(os.Stderr, "Error: unknown flag: '%s'\n", arg)
				return fmt.Errorf("unknown flag")
			}
			positional = append(positional, arg)
		}
		i++
	}

	if len(positional) != 2 {
		fmt.Fprintf(os.Stderr, "Error: accepts 2 arg(s), received %d\n", len(positional))
		fmt.Fprint(os.Stderr, importUsage)
		return fmt.Errorf("wrong number of args")
	}

	service := positional[0]
	fileArg := positional[1]

	var reader io.Reader
	if fileArg == "-" {
		reader = os.Stdin
	} else {
		f, err := os.Open(fileArg)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: Failed to open file: %v\n", err)
			return err
		}
		defer f.Close()
		reader = f
	}

	data, err := io.ReadAll(reader)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: Failed to read input: %v\n", err)
		return err
	}

	// Try JSON first, then YAML
	var secrets map[string]interface{}
	if err := json.Unmarshal(data, &secrets); err != nil {
		// Try YAML
		yamlSecrets, yamlErr := parseYAML(data)
		if yamlErr != nil {
			fmt.Fprintf(os.Stderr, "Error: Failed to decode input as json: %v\n", yamlErr)
			return yamlErr
		}
		secrets = yamlSecrets
	}

	store, err := a.getStore()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: Failed to get secret store: %v\n", err)
		return err
	}

	for k, v := range secrets {
		key := k
		if normalizeKeys {
			key = strings.ToLower(k)
		}
		var valueStr string
		switch tv := v.(type) {
		case string:
			valueStr = tv
		case float64:
			valueStr = strconv.FormatFloat(tv, 'f', -1, 64)
		case bool:
			valueStr = strconv.FormatBool(tv)
		default:
			b, _ := json.Marshal(v)
			valueStr = string(b)
		}
		id := SecretId{Service: service, Key: key}
		if err := store.Write(context.Background(), id, valueStr); err != nil {
			fmt.Fprintf(os.Stderr, "Error: Failed to write secret: %v\n", err)
			return err
		}
	}

	return nil
}

// Simple YAML parser for flat key-value format
func parseYAML(data []byte) (map[string]interface{}, error) {
	result := make(map[string]interface{})
	scanner := bufio.NewScanner(strings.NewReader(string(data)))
	lineNum := 0
	for scanner.Scan() {
		lineNum++
		line := scanner.Text()
		if strings.TrimSpace(line) == "" || strings.HasPrefix(strings.TrimSpace(line), "#") {
			continue
		}
		colonIdx := strings.Index(line, ":")
		if colonIdx < 0 {
			return nil, fmt.Errorf("[%d:%d] mapping value not found\n> %d | %s\n      ^", lineNum, len(line)+1, lineNum, line)
		}
		key := strings.TrimSpace(line[:colonIdx])
		value := strings.TrimSpace(line[colonIdx+1:])
		// Remove quotes
		if len(value) >= 2 && ((value[0] == '"' && value[len(value)-1] == '"') || (value[0] == '\'' && value[len(value)-1] == '\'')) {
			value = value[1 : len(value)-1]
		}
		// Check for sequence/mapping
		if strings.HasPrefix(value, "[") {
			// Try to parse but will error on malformed
			if !strings.HasSuffix(value, "]") {
				return nil, fmt.Errorf("[%d:%d] sequence end token ']' not found\n>  %d | %s\n                     ^", lineNum, len(line)+1, lineNum, line)
			}
		}
		result[key] = value
	}
	return result, nil
}

// runFind finds secrets
func (a *ChamberApp) runFind(args []string) error {
	byValue := false

	positional := []string{}
	i := 0
	for i < len(args) {
		arg := args[i]
		switch arg {
		case "--help", "-h":
			fmt.Fprint(os.Stdout, findUsage)
			return nil
		case "-v", "--by-value":
			byValue = true
		default:
			if strings.HasPrefix(arg, "-") {
				fmt.Fprintf(os.Stderr, "Error: unknown flag: '%s'\n", arg)
				return fmt.Errorf("unknown flag")
			}
			positional = append(positional, arg)
		}
		i++
	}

	if len(positional) != 1 {
		fmt.Fprintf(os.Stderr, "Error: accepts 1 arg(s), received %d\n", len(positional))
		fmt.Fprint(os.Stderr, findUsage)
		return fmt.Errorf("wrong number of args")
	}

	name := positional[0]

	store, err := a.getStore()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: Failed to get secret store: %v\n", err)
		return err
	}

	results, err := store.Find(context.Background(), name, byValue)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: Failed to find: %v\n", err)
		return err
	}

	if byValue {
		fmt.Printf("Service\t\tKey\n")
	} else {
		fmt.Printf("Service\t\tKey\n")
	}

	services := make([]string, 0, len(results))
	for svc := range results {
		services = append(services, svc)
	}
	sort.Strings(services)

	for _, svc := range services {
		fmt.Printf("%s\t\t%s\n", svc, results[svc])
	}

	return nil
}

// runTag handles tag subcommands
func (a *ChamberApp) runTag(args []string) error {
	if len(args) == 0 {
		fmt.Fprint(os.Stdout, tagUsage)
		return nil
	}

	cmd := args[0]
	cmdArgs := args[1:]

	switch cmd {
	case "read":
		return a.runTagRead(cmdArgs)
	case "write":
		return a.runTagWrite(cmdArgs)
	case "delete":
		return a.runTagDelete(cmdArgs)
	case "--help", "-h":
		fmt.Fprint(os.Stdout, tagUsage)
		return nil
	case "help":
		if len(cmdArgs) > 0 {
			switch cmdArgs[0] {
			case "read":
				fmt.Fprint(os.Stdout, tagReadUsage)
			case "write":
				fmt.Fprint(os.Stdout, tagWriteUsage)
			case "delete":
				fmt.Fprint(os.Stdout, tagDeleteUsage)
			default:
				fmt.Fprint(os.Stdout, tagUsage)
			}
		} else {
			fmt.Fprint(os.Stdout, tagUsage)
		}
		return nil
	default:
		fmt.Fprintf(os.Stderr, "Error: unknown command %q for \"chamber tag\"\nRun 'chamber tag --help' for usage.\n", cmd)
		return fmt.Errorf("unknown command")
	}
}

func (a *ChamberApp) runTagRead(args []string) error {
	positional := []string{}
	for _, arg := range args {
		if arg == "--help" || arg == "-h" {
			fmt.Fprint(os.Stdout, tagReadUsage)
			return nil
		}
		if !strings.HasPrefix(arg, "-") {
			positional = append(positional, arg)
		}
	}

	if len(positional) != 2 {
		fmt.Fprintf(os.Stderr, "Error: accepts 2 arg(s), received %d\n", len(positional))
		fmt.Fprint(os.Stderr, tagReadUsage)
		return fmt.Errorf("wrong number of args")
	}

	service := positional[0]
	key := positional[1]

	store, err := a.getStore()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: Failed to get secret store: %v\n", err)
		return err
	}

	id := SecretId{Service: service, Key: key}
	tags, err := store.ReadTagsForSecret(context.Background(), id)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: Failed to read tags: %v\n", err)
		return err
	}

	tagKeys := make([]string, 0, len(tags))
	for k := range tags {
		tagKeys = append(tagKeys, k)
	}
	sort.Strings(tagKeys)

	fmt.Printf("Key\tValue\n")
	for _, k := range tagKeys {
		fmt.Printf("%s\t%s\n", k, tags[k])
	}

	return nil
}

func (a *ChamberApp) runTagWrite(args []string) error {
	deleteOtherTags := false
	positional := []string{}
	i := 0
	for i < len(args) {
		arg := args[i]
		switch arg {
		case "--help", "-h":
			fmt.Fprint(os.Stdout, tagWriteUsage)
			return nil
		case "--delete-other-tags":
			deleteOtherTags = true
		default:
			if strings.HasPrefix(arg, "-") {
				fmt.Fprintf(os.Stderr, "Error: unknown flag: '%s'\n", arg)
				return fmt.Errorf("unknown flag")
			}
			positional = append(positional, arg)
		}
		i++
	}

	if len(positional) < 3 {
		fmt.Fprintf(os.Stderr, "Error: requires at least 3 arg(s), received %d\n", len(positional))
		fmt.Fprint(os.Stderr, tagWriteUsage)
		return fmt.Errorf("wrong number of args")
	}

	service := positional[0]
	key := positional[1]
	tagArgs := positional[2:]

	tags := make(map[string]string)
	for _, tag := range tagArgs {
		kv := strings.SplitN(tag, "=", 2)
		if len(kv) == 2 {
			tags[kv[0]] = kv[1]
		}
	}

	store, err := a.getStore()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: Failed to get secret store: %v\n", err)
		return err
	}

	id := SecretId{Service: service, Key: key}

	if deleteOtherTags {
		// Get existing tags and delete ones not in the new set
		existing, err := store.ReadTagsForSecret(context.Background(), id)
		if err == nil {
			var toDelete []string
			for k := range existing {
				if _, ok := tags[k]; !ok {
					toDelete = append(toDelete, k)
				}
			}
			if len(toDelete) > 0 {
				store.DeleteTagsForSecret(context.Background(), id, toDelete)
			}
		}
	}

	if err := store.WriteTagsForSecret(context.Background(), id, tags); err != nil {
		fmt.Fprintf(os.Stderr, "Error: Failed to write tags: %v\n", err)
		return err
	}

	return nil
}

func (a *ChamberApp) runTagDelete(args []string) error {
	positional := []string{}
	for _, arg := range args {
		if arg == "--help" || arg == "-h" {
