# This is getting complex. The goccy/go-yaml library's error format is quite detailed.
# Let me implement a proper YAML parser that:
# 1. Handles valid flat key-value YAML maps
# 2. Produces error messages that match goccy/go-yaml format

# The key cases I need to handle:
# - Valid map (key: value pairs) -> parse successfully
# - Sequences ([]) -> "sequence end token ']' not found" if not closed
# - Mappings ({}) -> "could not find flow mapping end token '}'" if not closed
# - Non-mapping at top level -> "... was used where mapping is expected"
# - JSON also works (handled by json.Unmarshal)

# Let me rewrite the parseYAML function with proper error messages

cat > /workspace/src/yaml_parser.go << 'GOEOF'
package main

import (
	"fmt"
	"strings"
)

// yamlError represents an error from YAML parsing in the goccy/go-yaml format
type yamlError struct {
	Line    int
	Col     int
	Message string
	Lines   []string // all lines of the input
}

func (e *yamlError) Error() string {
	return fmt.Sprintf("[%d:%d] %s\n%s", e.Line, e.Col, e.Message, e.formatContext())
}

func (e *yamlError) formatContext() string {
	if len(e.Lines) == 0 {
		return ""
	}

	var sb strings.Builder

	// Determine context window
	// Show up to 3 lines before error line and 3 lines after
	errIdx := e.Line - 1 // 0-indexed
	startIdx := errIdx - 3
	if startIdx < 0 {
		startIdx = 0
	}
	endIdx := errIdx + 3
	if endIdx >= len(e.Lines) {
		endIdx = len(e.Lines) - 1
	}

	// Format prefix for line numbers
	maxLineNum := endIdx + 1
	numWidth := len(fmt.Sprintf("%d", maxLineNum))
	if numWidth < 1 {
		numWidth = 1
	}

	// Show lines from startIdx to endIdx
	for i := startIdx; i <= endIdx; i++ {
		lineNum := i + 1
		numStr := fmt.Sprintf("%d", lineNum)
		spaces := strings.Repeat(" ", numWidth-len(numStr)+1) // right-align with space after

		if i == errIdx {
			sb.WriteString(fmt.Sprintf(">%s%s | %s\n", spaces, numStr, e.Lines[i]))
			// Add the ^ indicator
			// Prefix length = 1 (>) + spaces + numStr + " | " = 1 + spaces + len(numStr) + 3
			prefixLen := 1 + (numWidth - len(numStr) + 1) + len(numStr) + 3
			sb.WriteString(strings.Repeat(" ", prefixLen+e.Col-2) + "^\n")
		} else if i < errIdx {
			sb.WriteString(fmt.Sprintf(" %s%s | %s\n", spaces, numStr, e.Lines[i]))
		} else {
			// After error lines - no caret
			sb.WriteString(fmt.Sprintf(" %s%s | %s\n", spaces, numStr, e.Lines[i]))
		}
	}

	return sb.String()
}

// parseYAML parses a flat YAML key-value document
func parseYAML(data []byte) (map[string]interface{}, error) {
	input := string(data)
	lines := strings.Split(input, "\n")
	// Remove trailing empty line if present
	if len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}

	result := make(map[string]interface{})

	for i, line := range lines {
		lineNum := i + 1
		trimmed := strings.TrimSpace(line)

		// Skip empty lines and comments
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}

		// Check for sequence start
		if strings.HasPrefix(trimmed, "- ") || trimmed == "-" {
			return nil, &yamlError{
				Line:    lineNum,
				Col:     1,
				Message: "sequence was used where mapping is expected",
				Lines:   lines,
			}
		}

		// Check for plain scalar (no colon)
		colonIdx := strings.Index(trimmed, ":")
		if colonIdx < 0 {
