package main

import (
	"fmt"
	"strings"
)

// yamlError represents an error from YAML parsing in the goccy/go-yaml format
type yamlError struct {
	Line    int
	Col     int
	Message string
	Lines   []string // all lines of the input
}

func (e *yamlError) Error() string {
	return fmt.Sprintf("[%d:%d] %s\n%s", e.Line, e.Col, e.Message, e.formatContext())
}

func (e *yamlError) formatContext() string {
	if len(e.Lines) == 0 {
		return ""
	}

	errIdx := e.Line - 1 // 0-indexed

	// Context window: up to 3 preceding and 3 following lines
	startIdx := errIdx - 3
	if startIdx < 0 {
		startIdx = 0
	}
	endIdx := errIdx + 3
	if endIdx >= len(e.Lines) {
		endIdx = len(e.Lines) - 1
	}

	// Calculate number width for line number formatting
	maxLineNum := endIdx + 1
	numWidth := len(fmt.Sprintf("%d", maxLineNum))
	if numWidth < 2 {
		numWidth = 2
	}

	var sb strings.Builder

	for i := startIdx; i <= endIdx; i++ {
		lineNum := i + 1
		numStr := fmt.Sprintf("%d", lineNum)
		// Right-justify number in numWidth
		padding := strings.Repeat(" ", numWidth-len(numStr))

		if i == errIdx {
			// Error line with ">"
			sb.WriteString(fmt.Sprintf("> %s%s | %s\n", padding, numStr, e.Lines[i]))
			// Add the ^ indicator
			// Prefix: "> " (2 chars) + padding + numStr + " | " (3 chars) = total prefix
			prefixLen := 2 + len(padding) + len(numStr) + 3
			sb.WriteString(strings.Repeat(" ", prefixLen+e.Col-2) + "^\n")
		} else {
			// Context line with " " 
			sb.WriteString(fmt.Sprintf("  %s%s | %s\n", padding, numStr, e.Lines[i]))
		}
	}

	return sb.String()
}

// parseYAML parses a flat YAML key-value document
// Returns map[string]interface{} on success, *yamlError on failure
func parseYAML(data []byte) (map[string]interface{}, error) {
	input := string(data)
	lines := strings.Split(input, "\n")
	// Remove trailing empty line if present
	for len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}

	result := make(map[string]interface{})

	for i, line := range lines {
		lineNum := i + 1
		trimmed := strings.TrimSpace(line)

		// Skip empty lines and comments
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}

		// Check for sequence start (list items)
		if strings.HasPrefix(trimmed, "- ") || trimmed == "-" {
			return nil, &yamlError{
				Line:    lineNum,
				Col:     1,
				Message: "sequence was used where mapping is expected",
				Lines:   lines,
			}
		}

		// Look for colon to split key:value
		colonIdx := strings.Index(line, ":")
		trimmedColonIdx := strings.Index(trimmed, ":")

		if trimmedColonIdx < 0 {
			// No colon - this is a plain scalar, not a mapping
			typ := guessYAMLType(trimmed)
			return nil, &yamlError{
				Line:    lineNum,
				Col:     1,
				Message: typ + " was used where mapping is expected",
				Lines:   lines,
			}
		}

		// Has a colon - extract key and value
		key := strings.TrimSpace(trimmed[:trimmedColonIdx])
		valueStr := ""
		if trimmedColonIdx+1 < len(trimmed) {
			valueStr = strings.TrimSpace(trimmed[trimmedColonIdx+1:])
		}

		// Validate key
		if key == "" {
			return nil, &yamlError{
				Line:    lineNum,
				Col:     1,
				Message: "empty key is not allowed",
				Lines:   lines,
			}
		}

		// Handle flow sequence value
		if strings.HasPrefix(valueStr, "[") {
			// Find the column of "[" in the original line
			bracketPos := strings.Index(line, "[")
			bracketCol := 1
			if bracketPos >= 0 {
				bracketCol = bracketPos + 1
			}

			if !strings.HasSuffix(valueStr, "]") {
				// Check if it closes on a subsequent line
				for j := i + 1; j < len(lines); j++ {
					nextTrimmed := strings.TrimSpace(lines[j])
					if nextTrimmed == "" || strings.HasPrefix(nextTrimmed, "#") {
						continue
					}
					if strings.Contains(nextTrimmed, "]") {
						// Closed - handle multi-line sequence  
						// For now, treat as error on missing comma/bracket
						break
					}
					// Next line looks like a new key or other content
					if colonIdx2 := strings.Index(nextTrimmed, ":"); colonIdx2 >= 0 {
						return nil, &yamlError{
							Line:    j + 1,
							Col:     1,
							Message: "',' or ']' must be specified",
							Lines:   lines,
						}
					}
					// If it doesn't have a colon, it might be a continuation
					// Error at end of sequence
					return nil, &yamlError{
						Line:    lineNum,
						Col:     bracketCol,
						Message: "sequence end token ']' not found",
						Lines:   lines,
					}
				}
			}
		}

		// Handle flow mapping value
		if strings.HasPrefix(valueStr, "{") {
			// Find column of "{"
			bracePos := strings.Index(line, "{")
			braceCol := 1
			if bracePos >= 0 {
				braceCol = bracePos + 1
			}

			if !strings.HasSuffix(valueStr, "}") {
				return nil, &yamlError{
					Line:    lineNum,
					Col:     braceCol,
					Message: "could not find flow mapping end token '}'",
					Lines:   lines,
				}
			}
		}

		_ = colonIdx // suppress unused variable warning

		// Parse the value
		value := parseYAMLValue(valueStr)
		result[key] = value
	}

	return result, nil
}

func guessYAMLType(s string) string {
	if strings.EqualFold(s, "true") || strings.EqualFold(s, "false") {
		return "bool"
	}
	if strings.EqualFold(s, "null") || s == "~" {
		return "null"
	}
	// Check if it's a number
	numChars := true
	hasDot := false
	start := 0
	if len(s) > 0 && (s[0] == '-' || s[0] == '+') {
		start = 1
	}
	for _, c := range s[start:] {
		if c == '.' {
			if hasDot {
				numChars = false
				break
			}
			hasDot = true
		} else if c < '0' || c > '9' {
			numChars = false
			break
		}
	}
	if numChars && len(s) > start {
		if hasDot {
			return "float"
		}
		return "int"
	}
	return "string"
}

func parseYAMLValue(s string) interface{} {
	// Remove quotes
	if len(s) >= 2 {
		if (s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '\'' && s[len(s)-1] == '\'') {
			return s[1 : len(s)-1]
		}
	}

	// Null
	if s == "null" || s == "~" || s == "" {
		return ""
	}

	return s
}
