package main

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"sort"
	"strings"
	"time"
)

// SecretsManagerStore implements SecretStore using AWS Secrets Manager
// It stores all keys for a service in a single secret as JSON
type SecretsManagerStore struct {
	retries int
	region  string
	creds   awsCreds
}

func newSecretsManagerStore(retries int) (*SecretsManagerStore, error) {
	region := getRegion()
	return &SecretsManagerStore{
		retries: retries,
		region:  region,
	}, nil
}

func (s *SecretsManagerStore) ensureCreds() error {
	if s.creds.AccessKeyID != "" {
		return nil
	}
	creds, err := getAWSCredentials()
	if err != nil {
		return err
	}
	s.creds = creds
	return nil
}

func (s *SecretsManagerStore) signRequest(req *http.Request, body string) {
	ssmStore := &SSMStore{creds: s.creds, region: s.region}
	ssmStore.signRequest(req, body, "secretsmanager")
}

func (s *SecretsManagerStore) smRequest(ctx context.Context, action string, payload interface{}) ([]byte, error) {
	if err := s.ensureCreds(); err != nil {
		return nil, fmt.Errorf("operation error Secrets Manager: %s, %v", action, err)
	}

	body, err := json.Marshal(payload)
	if err != nil {
		return nil, err
	}

	url := fmt.Sprintf("https://secretsmanager.%s.amazonaws.com/", s.region)
	req, err := http.NewRequestWithContext(ctx, "POST", url, bytes.NewReader(body))
	if err != nil {
		return nil, err
	}
	req.Host = fmt.Sprintf("secretsmanager.%s.amazonaws.com", s.region)
	req.Header.Set("X-Amz-Target", "secretsmanager."+action)
	req.Header.Set("Content-Type", "application/x-amz-json-1.1")

	s.signRequest(req, string(body))

	client := &http.Client{Timeout: 30 * time.Second}
	resp, err := client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("operation error Secrets Manager: %s, %v", action, err)
	}
	defer resp.Body.Close()
	respBody, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, err
	}

	if resp.StatusCode != 200 {
		var errResp struct {
			Code    string `json:"__type"`
			Message string `json:"message"`
		}
		if jerr := json.Unmarshal(respBody, &errResp); jerr == nil && errResp.Code != "" {
			return nil, fmt.Errorf("operation error Secrets Manager: %s, %s: %s", action, errResp.Code, errResp.Message)
		}
		return nil, fmt.Errorf("operation error Secrets Manager: %s, HTTP %d", action, resp.StatusCode)
	}

	return respBody, nil
}

// getServiceSecret fetches the JSON map stored for a service
func (s *SecretsManagerStore) getServiceSecret(ctx context.Context, service string) (map[string]string, error) {
	payload := map[string]interface{}{
		"SecretId": service,
	}
	data, err := s.smRequest(ctx, "GetSecretValue", payload)
	if err != nil {
		return nil, err
	}
	var result struct {
		SecretString string `json:"SecretString"`
	}
	if err := json.Unmarshal(data, &result); err != nil {
		return nil, err
	}
	var secretMap map[string]string
	if err := json.Unmarshal([]byte(result.SecretString), &secretMap); err != nil {
		// Try to parse as string
		return map[string]string{}, nil
	}
	return secretMap, nil
}

// putServiceSecret stores the JSON map for a service
func (s *SecretsManagerStore) putServiceSecret(ctx context.Context, service string, secretMap map[string]string) error {
	secretJSON, err := json.Marshal(secretMap)
	if err != nil {
		return err
	}

	// Try to update first
	updatePayload := map[string]interface{}{
		"SecretId":     service,
		"SecretString": string(secretJSON),
	}
	_, err = s.smRequest(ctx, "PutSecretValue", updatePayload)
	if err != nil {
		// If not found, create it
		if strings.Contains(err.Error(), "ResourceNotFoundException") {
			createPayload := map[string]interface{}{
				"Name":         service,
				"SecretString": string(secretJSON),
			}
			_, err = s.smRequest(ctx, "CreateSecret", createPayload)
		}
	}
	return err
}

func (s *SecretsManagerStore) Write(ctx context.Context, id SecretId, value string) error {
	// Read existing secret for service
	secretMap, err := s.getServiceSecret(ctx, id.Service)
	if err != nil {
		// If the secret doesn't exist, create a new map
		if strings.Contains(err.Error(), "ResourceNotFoundException") {
			secretMap = make(map[string]string)
		} else {
			return err
		}
	}
	secretMap[strings.ToLower(id.Key)] = value
	return s.putServiceSecret(ctx, id.Service, secretMap)
}

func (s *SecretsManagerStore) Read(ctx context.Context, id SecretId, version int) (Secret, error) {
	secretMap, err := s.getServiceSecret(ctx, id.Service)
	if err != nil {
		return Secret{}, err
	}

	key := strings.ToLower(id.Key)
	v, ok := secretMap[key]
	if !ok {
		return Secret{}, fmt.Errorf("secret %s/%s not found", id.Service, id.Key)
	}
	return Secret{Value: &v}, nil
}

func (s *SecretsManagerStore) List(ctx context.Context, service string, includeValues bool) ([]SecretMetaData, error) {
	secretMap, err := s.getServiceSecret(ctx, service)
	if err != nil {
		return nil, err
	}

	var results []SecretMetaData
	for k := range secretMap {
		results = append(results, SecretMetaData{Key: k})
	}
	sort.Slice(results, func(i, j int) bool {
		return results[i].Key < results[j].Key
	})
	return results, nil
}

func (s *SecretsManagerStore) ListRaw(ctx context.Context, service string) (map[string]string, error) {
	secretMap, err := s.getServiceSecret(ctx, service)
	if err != nil {
		return nil, err
	}

	result := make(map[string]string)
	for k, v := range secretMap {
		result[strings.ToUpper(k)] = v
	}
	return result, nil
}

func (s *SecretsManagerStore) History(ctx context.Context, id SecretId) ([]HistoryEvent, error) {
	// Simplified - just return empty history
	return []HistoryEvent{}, nil
}

func (s *SecretsManagerStore) Delete(ctx context.Context, id SecretId) error {
	secretMap, err := s.getServiceSecret(ctx, id.Service)
	if err != nil {
		return err
	}

	key := strings.ToLower(id.Key)
	if _, ok := secretMap[key]; !ok {
		return fmt.Errorf("secret %s/%s not found", id.Service, id.Key)
	}
	delete(secretMap, key)
	return s.putServiceSecret(ctx, id.Service, secretMap)
}

func (s *SecretsManagerStore) ListServices(ctx context.Context, service string, includeSecretNames bool) ([]string, error) {
