package main

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"sort"
	"strings"
	"time"
)

// S3Store implements SecretStore using AWS S3
// Stores all keys for a service as a single JSON object
type S3Store struct {
	bucket      string
	kmsKeyAlias string
	useKMS      bool
	region      string
	creds       awsCreds
}

func newS3Store(bucket, kmsKeyAlias string) (*S3Store, error) {
	region := getRegion()
	useKMS := kmsKeyAlias != ""
	return &S3Store{
		bucket:      bucket,
		kmsKeyAlias: kmsKeyAlias,
		useKMS:      useKMS,
		region:      region,
	}, nil
}

func (s *S3Store) ensureCreds() error {
	if s.creds.AccessKeyID != "" {
		return nil
	}
	creds, err := getAWSCredentials()
	if err != nil {
		return err
	}
	s.creds = creds
	return nil
}

func (s *S3Store) s3URL(path string) string {
	return fmt.Sprintf("https://%s.s3.%s.amazonaws.com%s", s.bucket, s.region, path)
}

func (s *S3Store) s3Request(ctx context.Context, method, path string, body []byte, extraHeaders map[string]string) ([]byte, int, error) {
	if err := s.ensureCreds(); err != nil {
		return nil, 0, fmt.Errorf("resolve auth scheme: resolve endpoint: endpoint rule error, Invalid region: region was not a valid DNS name.")
	}

	host := fmt.Sprintf("%s.s3.%s.amazonaws.com", s.bucket, s.region)
	url := fmt.Sprintf("https://%s%s", host, path)

	var bodyReader io.Reader
	if body != nil {
		bodyReader = bytes.NewReader(body)
	}

	req, err := http.NewRequestWithContext(ctx, method, url, bodyReader)
	if err != nil {
		return nil, 0, err
	}
	req.Host = host

	for k, v := range extraHeaders {
		req.Header.Set(k, v)
	}

	// Sign the request
	ssmStore := &SSMStore{creds: s.creds, region: s.region}
	bodyStr := ""
	if body != nil {
		bodyStr = string(body)
	}
	ssmStore.signRequest(req, bodyStr, "s3")

	client := &http.Client{Timeout: 30 * time.Second}
	resp, err := client.Do(req)
	if err != nil {
		return nil, 0, err
	}
	defer resp.Body.Close()
	respBody, err := io.ReadAll(resp.Body)
	return respBody, resp.StatusCode, err
}

// serviceKey returns the S3 object key for a service
func (s *S3Store) serviceKey(service string) string {
	if s.useKMS {
		return "" // S3-KMS uses per-key objects
	}
	return service
}

// perKeyObjectKey returns the S3 object key for a specific secret (S3-KMS mode)
func (s *S3Store) perKeyObjectKey(id SecretId) string {
	return id.Service + "/" + strings.ToLower(id.Key)
}

// getServiceMap reads the JSON map for a service (S3 non-KMS mode)
func (s *S3Store) getServiceMap(ctx context.Context, service string) (map[string]string, error) {
	path := "/" + service
	respBody, code, err := s.s3Request(ctx, "GET", path, nil, nil)
	if err != nil {
		return nil, fmt.Errorf("operation error S3: GetObject, %v", err)
	}
	if code == 404 {
		return make(map[string]string), nil
	}
	if code != 200 {
		return nil, fmt.Errorf("operation error S3: GetObject, HTTP %d", code)
	}

	var secretMap map[string]string
	if err := json.Unmarshal(respBody, &secretMap); err != nil {
		return make(map[string]string), nil
	}
	return secretMap, nil
}

// putServiceMap writes the JSON map for a service (S3 non-KMS mode)
func (s *S3Store) putServiceMap(ctx context.Context, service string, secretMap map[string]string) error {
	body, err := json.Marshal(secretMap)
	if err != nil {
		return err
	}
	headers := map[string]string{
		"Content-Type": "application/json",
	}
	path := "/" + service
	respBody, code, err := s.s3Request(ctx, "PUT", path, body, headers)
	if err != nil {
		return err
	}
	if code != 200 {
		return fmt.Errorf("S3 PUT failed: %d %s", code, string(respBody))
	}
	return nil
}

// listKMSObjects lists all S3 objects with the service prefix (S3-KMS mode)
func (s *S3Store) listKMSObjects(ctx context.Context, service string) ([]string, error) {
	prefix := service + "/"
	path := fmt.Sprintf("/?list-type=2&prefix=%s", prefix)
	respBody, code, err := s.s3Request(ctx, "GET", path, nil, nil)
	if err != nil {
		return nil, fmt.Errorf("operation error S3: ListObjectsV2, %v", err)
	}
	if code != 200 {
		return nil, fmt.Errorf("operation error S3: ListObjectsV2, HTTP %d", code)
	}

	// Parse XML
	var keys []string
	lines := strings.Split(string(respBody), "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "<Key>") {
			key := strings.TrimSuffix(strings.TrimPrefix(line, "<Key>"), "</Key>")
			key = strings.TrimPrefix(key, prefix)
			if key != "" {
				keys = append(keys, key)
			}
		}
	}
	sort.Strings(keys)
	return keys, nil
}

func (s *S3Store) Write(ctx context.Context, id SecretId, value string) error {
	if s.useKMS {
		// S3-KMS: list objects first (check if versioning needed?), then put
		_, err := s.listKMSObjects(ctx, id.Service)
		if err != nil {
			return err
		}
		key := s.perKeyObjectKey(id)
		headers := map[string]string{
			"Content-Type": "text/plain",
		}
		if s.kmsKeyAlias != "" {
			headers["x-amz-server-side-encryption"] = "aws:kms"
			headers["x-amz-server-side-encryption-aws-kms-key-id"] = s.kmsKeyAlias
		}
		body := []byte(value)
		respBody, code, err := s.s3Request(ctx, "PUT", "/"+key, body, headers)
		if err != nil {
			return err
		}
		if code != 200 {
			return fmt.Errorf("S3 PUT failed: %d %s", code, string(respBody))
		}
		return nil
	}

	// S3 non-KMS: read existing, update, write
	secretMap, err := s.getServiceMap(ctx, id.Service)
	if err != nil {
		return err
	}
	secretMap[strings.ToLower(id.Key)] = value
	return s.putServiceMap(ctx, id.Service, secretMap)
}

func (s *S3Store) Read(ctx context.Context, id SecretId, version int) (Secret, error) {
	if s.useKMS {
		key := s.perKeyObjectKey(id)
		respBody, code, err := s.s3Request(ctx, "GET", "/"+key, nil, nil)
		if err != nil {
			return Secret{}, fmt.Errorf("operation error S3: GetObject, %v", err)
		}
		if code == 404 {
			return Secret{}, fmt.Errorf("secret not found: %s/%s", id.Service, id.Key)
		}
		if code != 200 {
