\tpayload := map[string]interface{}{
\t\t"Name": path,
\t}
\t_, err := s.ssmRequest(ctx, "DeleteParameter", payload)
\treturn err
}'''

new_delete = '''func (s *SSMStore) Delete(ctx context.Context, id SecretId) error {
\tpath := s.parameterPath(id)
\t// First check if parameter exists (GetParameters)
\tgetPayload := map[string]interface{}{
\t\t"Names":          []string{path},
\t\t"WithDecryption": true,
\t}
\t_, err := s.ssmRequest(ctx, "GetParameters", getPayload)
\tif err != nil {
\t\treturn err
\t}
\t// Now delete the parameter
\tdelPayload := map[string]interface{}{
\t\t"Name": path,
\t}
\t_, err = s.ssmRequest(ctx, "DeleteParameter", delPayload)
\treturn err
}'''

if old_delete in content:
    content = content.replace(old_delete, new_delete)
    print("Fixed Delete")
else:
    print("NOT FOUND: Delete")

with open('/workspace/src/ssm_store.go', 'w') as f:
    f.write(content)
EOF

